import type { NextConfig } from "next";
import path from "node:path";
import { withSentryConfig } from "@sentry/nextjs";

const nextConfig: NextConfig = {
  reactStrictMode: true,
  // Standalone output bundles only the files needed to run the server
  // into .next/standalone/, producing a ~100MB Docker image instead of
  // the ~1GB you'd get copying the full repo + node_modules. Required
  // for the Railway deployment Dockerfile.
  output: "standalone",
  turbopack: {
    root: path.resolve(__dirname),
  },
  images: {
    remotePatterns: [
      {
        protocol: "https",
        hostname: "pub-bb2e103a32db4e198524a2e9ed8f35b4.r2.dev",
      },
      {
        protocol: "https",
        hostname: "zkzontawprihrzpayeam.supabase.co",
      },
      {
        protocol: "https",
        hostname: "*.supabase.co",
      },
    ],
  },
  // TEMPORARY during BUBS schema migration (2026-04-11):
  // The frontend still has ~50 TSC errors because views in the new
  // BUBS compat layer return `never` type for updates (Postgres views
  // without writable triggers). Runtime works because the views +
  // INSTEAD OF triggers handle writes correctly — the type inference
  // is what's wrong, not the actual SQL.
  //
  // TODO after Phase C frontend rewrite: remove ignoreBuildErrors and
  // migrate the remaining ~50 type sites to query rankora_* tables
  // directly with account_id filters instead of legacy compat views.
  typescript: {
    ignoreBuildErrors: true,
  },
  async headers() {
    return [
      {
        source: "/:path*",
        headers: [
          {
            key: "Strict-Transport-Security",
            value: "max-age=63072000; includeSubDomains; preload",
          },
          { key: "X-Frame-Options", value: "DENY" },
          { key: "X-Content-Type-Options", value: "nosniff" },
          {
            key: "Referrer-Policy",
            value: "strict-origin-when-cross-origin",
          },
          {
            key: "Permissions-Policy",
            value: "camera=(), microphone=(), geolocation=()",
          },
          { key: "X-DNS-Prefetch-Control", value: "on" },
        ],
      },
    ];
  },
};

// Sentry build-time wrapper. Uploads source maps to Sentry when
// SENTRY_AUTH_TOKEN is set; otherwise runs as a no-op wrapper so
// builds don't fail in local dev or when the token is absent.
// Note: `disableLogger` and `automaticVercelMonitors` were moved
// under `webpack.*` in @sentry/nextjs v10; since we're on Turbopack
// we omit them — Sentry's own debug logs are already suppressed by
// the `silent` flag during CI builds.
export default withSentryConfig(nextConfig, {
  org: process.env.SENTRY_ORG,
  project: process.env.SENTRY_PROJECT || "rankora",
  silent: !process.env.CI,
  widenClientFileUpload: true,
});

import { z } from 'zod'

const envSchema = z.object({
  // App
  NEXT_PUBLIC_APP_URL: z.string().url(),
  NEXT_PUBLIC_APP_ENV: z.enum(['production', 'staging', 'preview', 'development']).default('development'),
  NODE_ENV: z.enum(['production', 'development', 'test']).default('development'),
  LOG_LEVEL: z.enum(['trace', 'debug', 'info', 'warn', 'error', 'fatal']).default('info'),

  // Supabase
  NEXT_PUBLIC_SUPABASE_URL: z.string().url(),
  NEXT_PUBLIC_SUPABASE_ANON_KEY: z.string().min(1),
  SUPABASE_SERVICE_ROLE_KEY: z.string().min(1).optional(),
  SUPABASE_JWT_SECRET: z.string().min(1).optional(),

  // Dodo Payments
  DODO_API_KEY: z.string().min(1).optional(),
  DODO_PAYMENTS_WEBHOOK_KEY: z
    .string()
    .refine((v) => v.startsWith('whsec_'), {
      message: 'DODO_PAYMENTS_WEBHOOK_KEY must start with whsec_',
    })
    .optional(),

  // Resend
  RESEND_API_KEY: z
    .string()
    .refine((v) => v.startsWith('re_'), {
      message: 'RESEND_API_KEY must start with re_',
    })
    .optional(),
  RESEND_FROM_EMAIL: z.string().email().optional(),

  // Sentry
  NEXT_PUBLIC_SENTRY_DSN: z.string().url().optional(),
  SENTRY_AUTH_TOKEN: z.string().optional(),
  SENTRY_ORG: z.string().optional(),
  SENTRY_PROJECT: z.string().optional(),

  // PostHog
  NEXT_PUBLIC_POSTHOG_KEY: z.string().min(1).optional(),
  NEXT_PUBLIC_POSTHOG_HOST: z.string().url().optional(),

  // Redis (Upstash — rate limiting + cache)
  UPSTASH_REDIS_REST_URL: z.string().url().optional(),
  UPSTASH_REDIS_REST_TOKEN: z.string().min(1).optional(),

  // Redis (private — BullMQ)
  REDIS_PRIVATE_URL: z.string().min(1).optional(),

  // AI (Sprint 9+)
  ANTHROPIC_API_KEY: z.string().min(1).optional(),
  AI_IMAGE_PROVIDER: z.enum(['openai', 'stability']).default('openai'),
  OPENAI_API_KEY: z.string().min(1).optional(),
  STABILITY_API_KEY: z.string().min(1).optional(),
})

/**
 * Validated environment variables.
 *
 * During build-time (NEXT_PUBLIC_* only available), Supabase anon key and URL
 * are always required. Server-only keys are optional so the build can run
 * without them — but will fail at runtime if a feature requires them.
 *
 * In production, DODO_PAYMENTS_WEBHOOK_KEY and RESEND_API_KEY are enforced
 * in the handlers that use them, not at boot time, to allow staging deploys
 * with partial secrets.
 */
function createEnv() {
  const result = envSchema.safeParse(process.env)

  if (!result.success) {
    const formatted = result.error.format()
    // Only throw in server runtime, not during static generation of public pages
    if (typeof window === 'undefined' && process.env.NODE_ENV !== 'test') {
      throw new Error(
        `[InkOS] Invalid environment variables:\n${JSON.stringify(formatted, null, 2)}`
      )
    }
    // Return partial in browser/test
    return process.env as unknown as z.infer<typeof envSchema>
  }

  return result.data
}

export const env = createEnv()

