import pino from 'pino'

/**
 * Structured pino logger.
 *
 * In production (Railway), outputs JSON that Railway aggregates and makes
 * searchable. In development, pino-pretty formats the output for readability.
 *
 * NEVER use console.log in production code — ESLint will block it.
 */
export const logger = pino({
  level: process.env.LOG_LEVEL ?? 'info',
  formatters: {
    level: (label) => ({ level: label }),
  },
  base: {
    env: process.env.NEXT_PUBLIC_APP_ENV ?? 'development',
    service: 'inkos-web',
    version: process.env.RAILWAY_DEPLOYMENT_ID ?? 'local',
  },
  redact: {
    paths: [
      'req.headers.authorization',
      'req.headers.cookie',
      '*.password',
      '*.token',
      '*.api_key',
      '*.apiKey',
      '*.secret',
      '*.webhook_key',
    ],
    censor: '[REDACTED]',
  },
  timestamp: pino.stdTimeFunctions.isoTime,
  ...(process.env.NODE_ENV === 'development' && {
    transport: {
      target: 'pino-pretty',
      options: {
        colorize: true,
        translateTime: 'HH:MM:ss',
        ignore: 'pid,hostname',
      },
    },
  }),
})

/**
 * Create a child logger with request-scoped context.
 */
export function requestLogger(requestId: string) {
  return logger.child({ requestId })
}

import type { Metadata } from 'next'
import { Geist, Geist_Mono } from 'next/font/google'
import { Toaster } from 'sonner'
import { ThemeProvider } from 'next-themes'
import { TooltipProvider } from '@/components/ui/tooltip'
import { QueryProvider } from '@/components/providers/QueryProvider'
import { WebVitalsReporter } from '@/components/providers/WebVitalsReporter'
import './globals.css'

const geistSans = Geist({
  variable: '--font-geist-sans',
  subsets: ['latin'],
})

const geistMono = Geist_Mono({
  variable: '--font-geist-mono',
  subsets: ['latin'],
})

export const metadata: Metadata = {
  title: {
    default: 'InkOS — Tattoo Studio OS',
    template: '%s | InkOS',
  },
  description: 'The operating system for modern tattoo studios.',
  robots: {
    index: false,
    follow: false,
  },
}

// Sprint 10 B8: viewportFit=cover enables env(safe-area-inset-*) on iOS notch devices
export const viewport = {
  viewportFit: 'cover' as const,
}

interface RootLayoutProps {
  children: React.ReactNode
}

export default function RootLayout({ children }: RootLayoutProps) {
  return (
    <html
      lang="en"
      suppressHydrationWarning
      className={`${geistSans.variable} ${geistMono.variable}`}
    >
      <body className="bg-background text-foreground antialiased" suppressHydrationWarning>
        {/* Skip navigation link — hidden until focused, satisfies WCAG 2.4.1 */}
        <a
          href="#main-content"
          className="sr-only focus:not-sr-only focus:fixed focus:top-4 focus:left-4 focus:z-[200] focus:rounded-lg focus:bg-primary focus:px-4 focus:py-2 focus:text-sm focus:font-semibold focus:text-primary-foreground focus:shadow-overlay focus:outline-none"
        >
          Skip to main content
        </a>
        <ThemeProvider
          attribute="class"
          defaultTheme="light"
          disableTransitionOnChange
        >
          <QueryProvider>
            <TooltipProvider>
              {children}
            </TooltipProvider>
          </QueryProvider>
          <WebVitalsReporter />
          <Toaster
            position="top-right"
            richColors
            closeButton
            duration={4000}
            toastOptions={{
              classNames: {
                toast: 'rounded-xl backdrop-blur-sm',
                title: 'font-semibold',
                description: 'text-muted-foreground',
              },
            }}
          />
        </ThemeProvider>
      </body>
    </html>
  )
}

'use client'

/**
 * WebVitalsReporter — thin client component.
 * Subscribes to Core Web Vitals (LCP, INP, CLS, FCP, TTFB) and forwards
 * them to Sentry Performance + PostHog for RUM.
 *
 * Uses dynamic import so the web-vitals bundle is not in the critical path.
 */
import { useEffect } from 'react'

export function WebVitalsReporter() {
  useEffect(() => {
    async function init() {
      const { onLCP, onINP, onCLS, onFCP, onTTFB } = await import('web-vitals')

      function report(metric: {
        name: string
        value: number
        rating: string
        id: string
      }) {
        // Sentry
        if (typeof window !== 'undefined' && 'Sentry' in window) {
          const sentry = (window as unknown as { Sentry: { captureEvent: (e: unknown) => void } }).Sentry
          sentry.captureEvent({
            message: `Web Vital: ${metric.name}`,
            level: 'info',
            extra: {
              name: metric.name,
              value: metric.value,
              rating: metric.rating,
              id: metric.id,
            },
          })
        }

        // PostHog (if available)
        if (typeof window !== 'undefined' && 'posthog' in window) {
          const ph = (window as unknown as { posthog: { capture: (name: string, props: unknown) => void } }).posthog
          ph.capture('web_vital', {
            name: metric.name,
            value: metric.value,
            rating: metric.rating,
          })
        }
      }

      onLCP(report)
      onINP(report)
      onCLS(report)
      onFCP(report)
      onTTFB(report)
    }

    void init()
  }, [])

  return null
}

'use client'

import { QueryClientProvider } from '@tanstack/react-query'
import { ReactQueryDevtools } from '@tanstack/react-query-devtools'
import { getQueryClient } from '@/lib/query-client'

interface QueryProviderProps {
  children: React.ReactNode
}

export function QueryProvider({ children }: QueryProviderProps) {
  const queryClient = getQueryClient()

  return (
    <QueryClientProvider client={queryClient}>
      {children}
      {process.env.NODE_ENV === 'development' && (
        <ReactQueryDevtools initialIsOpen={false} />
      )}
    </QueryClientProvider>
  )
}

