'use client'

import { useRef } from 'react'
import { useRouter, usePathname } from 'next/navigation'
import { cn } from '@/lib/utils'
import { PlanBadge } from '@/components/shared/PlanBadge'
import { PLAN_ORDER } from '@/lib/billing/feature-gate'
import type { PlanTier } from '@/lib/billing/feature-gate'
import type { NavRole } from '@/components/app/sidebar/nav-config'

export interface PageTab {
  key: string
  label: string
  href: string
  badge?: number | string
  gated?: PlanTier
  /** Return true to hide this tab for the given role */
  hidden?: (role: NavRole) => boolean
}

export interface PageTabsProps {
  tabs: PageTab[]
  activeKey: string
  currentPlan: PlanTier
  currentRole: NavRole
  className?: string
}

/**
 * S13 — Horizontal underline tab row with URL persistence via ?tab= query param.
 *
 * Accessibility:
 *  - role="tablist" on container
 *  - role="tab" + aria-selected on each trigger
 *  - Arrow key navigation within the tab row (ARIA authoring practices)
 *  - focus-visible ring on each trigger
 *
 * URL persistence:
 *  - Active tab read from ?tab= param by parent; defaulted to tabs[0].key if absent/invalid
 *  - Navigates via router.replace({pathname}?tab={key}, { scroll: false }) — no full reload
 *
 * Plan gating:
 *  - If tab.gated is set and user plan is below requirement, renders tab at reduced opacity
 *  - Click on gated tab routes to /settings/billing
 */
export function PageTabs({ tabs, activeKey, currentPlan, currentRole, className }: PageTabsProps) {
  const router = useRouter()
  const pathname = usePathname()
  const listRef = useRef<HTMLDivElement>(null)

  const visibleTabs = tabs.filter((t) => !(t.hidden?.(currentRole) ?? false))

  function isLocked(tab: PageTab): boolean {
    return tab.gated != null && PLAN_ORDER[currentPlan] < PLAN_ORDER[tab.gated]
  }

  function handleSelect(tab: PageTab) {
    if (isLocked(tab)) {
      router.push('/settings/billing')
      return
    }
    router.replace(`${pathname}?tab=${tab.key}`, { scroll: false })
  }

  function handleKeyDown(e: React.KeyboardEvent<HTMLButtonElement>, currentIndex: number) {
    const triggers = listRef.current?.querySelectorAll<HTMLButtonElement>('[role="tab"]')
    if (!triggers) return

    let nextIndex: number | null = null

    if (e.key === 'ArrowRight') {
      nextIndex = (currentIndex + 1) % triggers.length
    } else if (e.key === 'ArrowLeft') {
      nextIndex = (currentIndex - 1 + triggers.length) % triggers.length
    } else if (e.key === 'Home') {
      nextIndex = 0
    } else if (e.key === 'End') {
      nextIndex = triggers.length - 1
    }

    if (nextIndex !== null) {
      e.preventDefault()
      triggers[nextIndex]?.focus()
    }
  }

  return (
    <div
      ref={listRef}
      role="tablist"
      aria-label="Page sections"
      className={cn(
        'flex items-end gap-0 border-b border-border/60',
        'overflow-x-auto scrollbar-none',
        // Fade edges on mobile only
        '[mask-image:linear-gradient(to_right,transparent_0px,black_16px,black_calc(100%-16px),transparent_100%)]',
        'md:[mask-image:none]',
        className,
      )}
    >
      {visibleTabs.map((tab, index) => {
        const isActive = tab.key === activeKey
        const locked = isLocked(tab)

        return (
          <button
            key={tab.key}
            type="button"
            role="tab"
            aria-selected={isActive}
            onClick={() => handleSelect(tab)}
            onKeyDown={(e) => handleKeyDown(e, index)}
            className={cn(
              'relative flex items-center gap-1.5 px-3 h-10 shrink-0',
              'text-sm whitespace-nowrap transition-colors duration-150',
              'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-0',
              isActive
                ? [
                    'font-semibold text-foreground',
                    'after:absolute after:bottom-0 after:inset-x-0 after:h-0.5 after:bg-primary after:rounded-full',
                  ]
                : 'font-medium text-muted-foreground hover:text-foreground',
              locked && 'opacity-60 cursor-default',
            )}
          >
            {tab.label}
            {tab.gated != null && <PlanBadge plan={tab.gated} />}
            {tab.badge != null && (
              <span className="inline-flex items-center rounded-full bg-muted text-muted-foreground text-[10px] font-semibold leading-none px-1.5 py-0.5 min-w-[18px] justify-center tabular-nums">
                {tab.badge}
              </span>
            )}
          </button>
        )
      })}
    </div>
  )
}

'use client'

import { useRef } from 'react'
import { toast } from 'sonner'
import { CurrentPlanCard, CurrentPlanCardSkeleton } from '@/components/billing/CurrentPlanCard'
import { PlanSelector } from '@/components/billing/PlanSelector'
import { UsageMeters } from '@/components/billing/UsageMeters'
import { InvoiceTable } from '@/components/billing/InvoiceTable'
import { PaymentMethodCard } from '@/components/billing/PaymentMethodCard'
import { TrialBanner } from '@/components/billing/TrialBanner'
import { QuotaExceededBanner } from '@/components/billing/QuotaExceededBanner'
import type { StudioSubscriptionRpc, BillingSummaryRpc } from '@/lib/billing/schemas'
import { Typography } from '@/components/ui/typography'

interface BillingPageClientProps {
  subscription: StudioSubscriptionRpc['subscription'] | null
  plan?: StudioSubscriptionRpc['plan']
  plans: StudioSubscriptionRpc['plan'][]
  usage: BillingSummaryRpc['current_usage']
  invoices: Array<{
    id: string
    dodo_invoice_id: string
    amount_cents: number
    tax_cents: number | null
    currency: string
    status: 'draft' | 'open' | 'paid' | 'uncollectible' | 'void' | 'refunded'
    period_start: string | null
    period_end: string | null
    paid_at: string | null
    due_date: string | null
    pdf_url: string | null
    hosted_url: string | null
    created_at: string
  }>
  isOwner: boolean
}

export function BillingPageClient({
  subscription,
  plan,
  plans,
  usage,
  invoices,
  isOwner,
}: BillingPageClientProps) {
  const planSelectorRef = useRef<HTMLDivElement>(null)

  function scrollToPlanSelector() {
    planSelectorRef.current?.scrollIntoView({ behavior: 'smooth', block: 'start' })
  }

  async function handleCancel() {
    const res = await fetch('/api/billing/cancel', { method: 'POST' })
    const json = await res.json() as { error?: string }
    if (!res.ok) throw new Error(json.error ?? 'Failed to cancel')
  }

  async function handleResume() {
    const res = await fetch('/api/billing/resume', { method: 'POST' })
    const json = await res.json() as { error?: string }
    if (!res.ok) {
      toast.error(json.error ?? 'Failed to resume subscription')
      return
    }
    toast.success('Subscription resumed')
  }

  async function openPortal() {
    const res = await fetch('/api/billing/portal')
    const json = await res.json() as { url?: string; error?: string }
    if (!res.ok || !json.url) {
      toast.error(json.error ?? 'Could not open billing portal')
      return
    }
    window.location.href = json.url
  }

  const hasUsage = Object.keys(usage).length > 0

  return (
    <div className="space-y-8">
      {/* Quota exceeded banner */}
      {hasUsage && (
        <QuotaExceededBanner usage={usage} onUpgrade={scrollToPlanSelector} />
      )}

      {/* Trial banner */}
      {subscription?.status === 'trialing' && (
        <TrialBanner subscription={subscription} onUpgrade={scrollToPlanSelector} />
      )}

      {/* Current plan card */}
      {subscription && plan ? (
        <CurrentPlanCard
          subscription={subscription}
          plan={plan}
          onChangePlan={scrollToPlanSelector}
          onOpenPortal={openPortal}
          onCancel={handleCancel}
          onResume={handleResume}
        />
      ) : (
        subscription === null && <CurrentPlanCardSkeleton />
      )}

      {/* Plan selector */}
      <section ref={planSelectorRef} className="rounded-xl border border-border/60 p-6 space-y-4">
        <div>
          <Typography variant="h3" as="h2">Choose a plan</Typography>
          <p className="text-sm text-muted-foreground mt-0.5">All plans include a 14-day free trial. Cancel anytime.</p>
        </div>
        {subscription ? (
          <PlanSelector plans={plans} subscription={subscription} />
        ) : (
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
            {plans.slice(0, 4).map((p) => (
              <div key={p.tier} className="rounded-xl border border-border/60 p-5 space-y-3">
                <p className="text-xs font-semibold uppercase tracking-widest text-muted-foreground">{p.tier}</p>
              </div>
            ))}
          </div>
        )}
      </section>

      {/* Usage meters */}
      {hasUsage && (
        <UsageMeters usage={usage} onAddCapacity={scrollToPlanSelector} />
      )}

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        {/* Invoice table — 2/3 width */}
        <section className="lg:col-span-2 rounded-xl border border-border/60 p-6 space-y-4">
          <Typography variant="h3" as="h2">Invoices</Typography>
          <InvoiceTable invoices={invoices} />
        </section>

        {/* Payment method — 1/3 width */}
        {isOwner && (
          <div className="space-y-4">
            <PaymentMethodCard />
          </div>
        )}
      </div>
    </div>
  )
}

import type { Metadata } from 'next'
import { redirect } from 'next/navigation'
import { createClient, getAuthenticatedUser } from '@/lib/supabase/server'
import { StudioSubscriptionRpcSchema, BillingSummaryRpcSchema } from '@/lib/billing/schemas'
import { BillingPageClient } from './BillingPageClient'
import { Skeleton } from '@/components/ui/skeleton'
import { Suspense } from 'react'
import { Typography } from '@/components/ui/typography'

export const metadata: Metadata = {
  title: 'Billing & Plan — InkOS',
}

async function BillingContent() {
  const auth = await getAuthenticatedUser()
  if (!auth) redirect('/login')

  const supabase = await createClient()

  // Fetch all billing data in parallel
  const [subRpc, summaryRpc, plansResult, invoicesResult] = await Promise.all([
    supabase.rpc('get_studio_subscription', { p_studio_id: auth.studioId }),
    supabase.rpc('get_billing_summary', { p_studio_id: auth.studioId }),
    supabase
      .from('plans')
      .select('id, tier, billing_cycle, display_name, price_cents, currency, max_artists, max_locations, sms_monthly_quota, ai_generations_quota, features, sort_order')
      .eq('is_active', true)
      .order('sort_order', { ascending: true }),
    supabase
      .from('invoices')
      .select('id, dodo_invoice_id, amount_cents, tax_cents, currency, status, period_start, period_end, paid_at, due_date, pdf_url, hosted_url, created_at')
      .eq('studio_id', auth.studioId)
      .order('created_at', { ascending: false })
      .limit(20),
  ])

  const subscriptionParsed = StudioSubscriptionRpcSchema.safeParse(subRpc.data)
  const summaryParsed = BillingSummaryRpcSchema.safeParse(summaryRpc.data)

  if (!subscriptionParsed.success || !summaryParsed.success) {
    // Subscription row may not exist yet for brand-new studios
    return (
      <div className="p-6 max-w-5xl space-y-8">
        <div>
          <Typography variant="h1">Billing &amp; Plan</Typography>
          <p className="mt-1 text-sm text-muted-foreground">Set up billing to access all InkOS features.</p>
        </div>
        <BillingPageClient
          subscription={null}
          plans={plansResult.data ?? []}
          usage={{}}
          invoices={invoicesResult.data ?? []}
          isOwner={auth.role === 'owner'}
        />
      </div>
    )
  }

  return (
    <div className="p-6 max-w-5xl space-y-8">
      <div>
        <Typography variant="h1">Billing &amp; Plan</Typography>
        <p className="mt-1 text-sm text-muted-foreground">Manage your subscription and usage.</p>
      </div>
      <BillingPageClient
        subscription={subscriptionParsed.data.subscription}
        plan={subscriptionParsed.data.plan}
        plans={plansResult.data ?? []}
        usage={summaryParsed.data.current_usage}
        invoices={invoicesResult.data ?? []}
        isOwner={auth.role === 'owner'}
      />
    </div>
  )
}

export default function Page() {
  return (
    <Suspense
      fallback={
        <div className="p-6 max-w-5xl space-y-8">
          <Skeleton className="h-8 w-48" />
          <Skeleton className="h-4 w-64" />
          <Skeleton className="h-40 w-full rounded-xl" />
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
            {Array.from({ length: 4 }).map((_, i) => <Skeleton key={i} className="h-64 rounded-xl" />)}
          </div>
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            {Array.from({ length: 4 }).map((_, i) => <Skeleton key={i} className="h-28 rounded-xl" />)}
          </div>
        </div>
      }
    >
      <BillingContent />
    </Suspense>
  )
}

