import type { PageTab } from './PageTabs'
import type { NavRole } from '@/components/app/sidebar/nav-config'

/**
 * Resolve role-gated visibility on the server before passing tabs to the
 * client `<PageTabs>` component. Functions cannot cross the RSC boundary.
 */
export function filterTabsForRole(
  tabs: PageTab[],
  role: NavRole,
): Omit<PageTab, 'hidden'>[] {
  return tabs
    .filter((t) => !(t.hidden?.(role) ?? false))
    .map(({ hidden: _hidden, ...rest }) => rest)
}

