import type { NavRole } from '@/components/app/sidebar/nav-config'

export const metadata: Metadata = {
  title: 'Appointments — InkOS',
}

const APPOINTMENTS_TABS: PageTab[] = [
  {
    key: 'list',
    label: 'All',
    href: '/appointments?tab=list',
  },
  {
    key: 'today',
    label: 'Today',
    href: '/appointments?tab=today',
  },
  {
    key: 'waitlist',
    label: 'Waitlist',
    href: '/appointments?tab=waitlist',
    hidden: (role) =>
      role !== 'owner' && role !== 'admin' && role !== 'receptionist',
  },
]

const VALID_KEYS = new Set(APPOINTMENTS_TABS.map((t) => t.key))

interface Props {
  searchParams: Promise<Record<string, string | string[] | undefined>>
}

export default async function AppointmentsPage({ searchParams }: Props) {
  const auth = await getAuthenticatedUser()
  if (!auth) redirect('/login')

  const supabase = await createClient()
  let plan: PlanTier = 'solo'
  const { data: sub } = await supabase
    .from('subscriptions')
    .select('plan_tier')
    .eq('studio_id', auth.studioId)
    .eq('status', 'active')
    .maybeSingle()
  if (sub?.plan_tier) plan = sub.plan_tier as PlanTier

  const role = auth.role as NavRole
  const params = await searchParams
  const rawTab = typeof params.tab === 'string' ? params.tab : undefined
  const activeKey = rawTab && VALID_KEYS.has(rawTab) ? rawTab : 'list'

  return (
    <div className="flex flex-col flex-1 min-h-0">
      {/* Page header */}
      <div className="flex items-center justify-between px-6 pt-6 pb-0">
        <div>
          <h1 className="text-2xl font-bold tracking-tight text-foreground">Appointments</h1>
          <p className="mt-0.5 text-sm text-muted-foreground">Manage all studio bookings</p>
        </div>
      </div>

      {/* Tab row */}
      <div className="px-6 mt-4">
        <PageTabs
          tabs={filterTabsForRole(APPOINTMENTS_TABS, role)}
          activeKey={activeKey}
          currentPlan={plan}
          currentRole={role}
        />
      </div>

      {/* Tab content */}
      <div role="tabpanel" id={`tabpanel-${activeKey}`} className="flex flex-col flex-1 min-h-0">
        <Suspense fallback={<div className="flex-1 animate-pulse bg-muted/20 m-6 rounded-xl" />}>
          {activeKey === 'list' && <AppointmentsPageClient />}
          {activeKey === 'today' && <AppointmentsPageClient forceToday />}
          {activeKey === 'waitlist' && <WaitlistPageClient />}
        </Suspense>
      </div>
    </div>
  )
}

import type { Metadata } from 'next'
import { redirect } from 'next/navigation'
import { Suspense } from 'react'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { listProjects } from '@/lib/projects/queries'
import { ProjectsListClient } from '@/components/projects/ProjectsListClient'
import { Skeleton } from '@/components/ui/skeleton'
import type { ListProjectsFilters } from '@/lib/projects/queries'
import type { ProjectStatus } from '@/lib/projects/queries'

export const metadata: Metadata = {
  title: 'Projects — InkOS',
}

interface Props {
  searchParams: Promise<Record<string, string | string[] | undefined>>
}

export default async function ProjectsPage({ searchParams }: Props) {
  const auth = await getAuthenticatedUser()
  if (!auth) redirect('/login')

  const params = await searchParams

  const getParam = (key: string) =>
    typeof params[key] === 'string' ? (params[key] as string) : undefined

  const filters: ListProjectsFilters = {}
  const statusParam = getParam('status')
  if (statusParam && ['active', 'completed', 'on_hold', 'cancelled'].includes(statusParam)) {
    filters.status = statusParam as ProjectStatus
  }
  const artistIdParam = getParam('artistId')
  if (artistIdParam) filters.artistId = artistIdParam
  const clientIdParam = getParam('clientId')
  if (clientIdParam) filters.clientId = clientIdParam
  const searchParam = getParam('search')
  if (searchParam) filters.search = searchParam

  const supabase = await createClient()

  const [projects, artistsResult] = await Promise.all([
    listProjects(auth.studioId, filters),
    supabase
      .from('artists')
      .select('id, display_name, avatar_url, sort_order')
      .eq('studio_id', auth.studioId)
      .eq('status', 'active')
      .order('sort_order'),
  ])

  const artists = artistsResult.data ?? []

  return (
    <div className="flex flex-col flex-1 min-h-0">
      <Suspense
        fallback={
          <div className="p-6 grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
            {Array.from({ length: 8 }).map((_, i) => (
              <Skeleton key={i} className="h-64 rounded-xl" />
            ))}
          </div>
        }
      >
        <ProjectsListClient
          initialProjects={projects}
          artists={artists}
          role={auth.role}
          initialFilters={filters}
        />
      </Suspense>
    </div>
  )
}

