'use client'

import { useState, useCallback } from 'react'
import { UserPlus, Trash2, Users } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Slider } from '@/components/ui/slider'
import { Label } from '@/components/ui/label'
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select'
import { cn } from '@/lib/utils'
import { validateSplitSum } from '@/lib/bookings/participants'
import type { ParticipantRole } from '@/lib/bookings/participants'

export interface ParticipantEntry {
  artist_id: string
  artist_name: string
  role: ParticipantRole
  split_pct: number
  notes?: string | null
}

interface ArtistOption {
  id: string
  display_name: string
}

interface BookingParticipantsFieldProps {
  participants: ParticipantEntry[]
  onChange: (participants: ParticipantEntry[]) => void
  primaryArtistId: string | null
  availableArtists: ArtistOption[]
}

const ROLE_OPTIONS: { value: ParticipantRole; label: string }[] = [
  { value: 'primary', label: 'Primary' },
  { value: 'assistant', label: 'Assistant' },
  { value: 'piercer', label: 'Piercer' },
  { value: 'apprentice', label: 'Apprentice' },
  { value: 'observer', label: 'Observer' },
]

export function BookingParticipantsField({
  participants,
  onChange,
  primaryArtistId,
  availableArtists,
}: BookingParticipantsFieldProps) {
  const [addingArtistId, setAddingArtistId] = useState<string>('')

  const { ok: splitValid, total: splitTotal } = validateSplitSum(participants)

  const usedArtistIds = new Set(participants.map((p) => p.artist_id))
  const unassignedArtists = availableArtists.filter((a) => !usedArtistIds.has(a.id))

  const updateParticipant = useCallback(
    (index: number, patch: Partial<ParticipantEntry>) => {
      const next = participants.map((p, i) => (i === index ? { ...p, ...patch } : p))

      // Enforce single primary: if we're setting this one to primary, demote the old primary
      if (patch.role === 'primary') {
        const updated = next.map((p, i) => {
          if (i !== index && p.role === 'primary') {
            return { ...p, role: 'assistant' as ParticipantRole }
          }
          return p
        })
        onChange(updated)
        return
      }

      onChange(next)
    },
    [participants, onChange],
  )

  const removeParticipant = useCallback(
    (index: number) => {
      // Can't remove the primary unless there's another participant to promote
      if (participants[index]?.role === 'primary' && participants.length > 1) {
        const next = participants.filter((_, i) => i !== index)
        // Promote first remaining to primary
        if (next[0]) next[0] = { ...next[0], role: 'primary' }
        onChange(next)
        return
      }
      if (participants.length === 1) return // Can't remove last
      onChange(participants.filter((_, i) => i !== index))
    },
    [participants, onChange],
  )

  const addParticipant = useCallback(() => {
    if (!addingArtistId) return
    const artist = availableArtists.find((a) => a.id === addingArtistId)
    if (!artist) return

    const newEntry: ParticipantEntry = {
      artist_id: artist.id,
      artist_name: artist.display_name,
      role: 'assistant',
      split_pct: 0,
    }
    onChange([...participants, newEntry])
    setAddingArtistId('')
  }, [addingArtistId, availableArtists, participants, onChange])

  const distributeEvenly = useCallback(() => {
    if (participants.length === 0) return
    const base = Math.floor(100 / participants.length)
    const remainder = 100 - base * participants.length
    const next = participants.map((p, i) => ({
      ...p,
      split_pct: i === 0 ? base + remainder : base,
    }))
    onChange(next)
  }, [participants, onChange])

  return (
    <div className="space-y-3">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-1.5">
          <Users className="h-4 w-4 text-muted-foreground" />
          <span className="text-sm font-medium text-foreground">Participants</span>
        </div>
        <div className="flex items-center gap-2">
          {participants.length > 1 && (
            <Button
              type="button"
              variant="ghost"
              size="sm"
              className="h-7 text-xs px-2"
              onClick={distributeEvenly}
            >
              Distribute evenly
            </Button>
          )}
          {/* Split total indicator */}
          <span
            className={cn(
              'text-xs font-medium tabular-nums',
              splitValid ? 'text-green-600 dark:text-green-400' : 'text-destructive',
            )}
          >
            {splitTotal.toFixed(0)}%
          </span>
        </div>
      </div>

      {/* Participant rows */}
      <div className="space-y-2">
        {participants.map((participant, index) => (
          <div
            key={participant.artist_id}
            className="rounded-lg border border-border/50 bg-muted/20 p-3 space-y-2.5"
          >
            <div className="flex items-center justify-between gap-2">
              <div className="flex items-center gap-2 min-w-0 flex-1">
                {/* Artist name */}
                <span className="text-sm font-medium truncate">{participant.artist_name}</span>
                {participant.artist_id === primaryArtistId && (
                  <span className="shrink-0 inline-flex h-4 items-center rounded-full bg-primary/10 px-1.5 text-[9px] font-medium text-primary">
                    Booking artist
                  </span>
                )}
              </div>

              {/* Role picker */}
              <Select
                value={participant.role}
                onValueChange={(val) =>
                  updateParticipant(index, { role: val as ParticipantRole })
                }
              >
                <SelectTrigger className="h-7 w-[130px] text-xs shrink-0">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  {ROLE_OPTIONS.map((r) => (
                    <SelectItem key={r.value} value={r.value} className="text-xs">
                      {r.label}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>

              {/* Remove button — can't remove when only one participant */}
              <Button
                type="button"
                variant="ghost"
                size="icon"
                className="h-7 w-7 shrink-0 text-muted-foreground hover:text-destructive"
                onClick={() => removeParticipant(index)}
                disabled={participants.length === 1}
                aria-label={`Remove ${participant.artist_name}`}
              >
                <Trash2 className="h-3.5 w-3.5" />
              </Button>
            </div>

            {/* Split pct slider */}
            <div className="space-y-1">
              <div className="flex items-center justify-between">
                <Label className="text-xs text-muted-foreground">Split</Label>
                <span className="text-xs font-medium tabular-nums">
                  {participant.split_pct}%
                </span>
              </div>
              <Slider
                min={0}
                max={100}
                step={1}
                value={[participant.split_pct]}
                onValueChange={([val]) =>
                  updateParticipant(index, { split_pct: val ?? 0 })
                }
                className="w-full"
                aria-label={`Split percentage for ${participant.artist_name}`}
              />
            </div>
          </div>
        ))}
      </div>

      {/* Validation message */}
      {!splitValid && participants.length > 0 && (
        <p className="text-xs text-destructive" role="alert">
          Split percentages must total 100% (currently {splitTotal.toFixed(1)}%)
        </p>
      )}

      {/* Add participant */}
      {unassignedArtists.length > 0 && (
        <div className="flex items-center gap-2">
          <Select value={addingArtistId} onValueChange={setAddingArtistId}>
            <SelectTrigger className="h-8 flex-1 text-xs">
              <SelectValue placeholder="Add artist..." />
            </SelectTrigger>
            <SelectContent>
              {unassignedArtists.map((a) => (
                <SelectItem key={a.id} value={a.id} className="text-xs">
                  {a.display_name}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
          <Button
            type="button"
            variant="outline"
            size="sm"
            className="h-8 shrink-0"
            onClick={addParticipant}
            disabled={!addingArtistId}
            aria-label="Add participant"
          >
            <UserPlus className="h-3.5 w-3.5" />
          </Button>
        </div>
      )}
    </div>
  )
}

