function OwnerHero() {
  const queueQuery = useTodayQueue(true)
  return (
    <div className="space-y-3">
      <SectionLabel>Today&apos;s Queue</SectionLabel>
      <TodayQueue
        bookings={queueQuery.data ?? []}
        isLoading={queueQuery.isLoading}
        onRefresh={() => void queueQuery.refetch()}
      />
    </div>
  )
}

function ArtistHero({
  ownArtistId,
  artistEarningsToday,
}: {
  ownArtistId: string | null | undefined
  artistEarningsToday: number
}) {
  const queueQuery = useTodayQueue(true, ownArtistId ?? undefined)
  const bookings = queueQuery.data ?? []

  return (
    <div className="space-y-3">
      <SectionLabel>My Chair Today</SectionLabel>
      <TodayQueue
        bookings={bookings}
        isLoading={queueQuery.isLoading}
        onRefresh={() => void queueQuery.refetch()}
