        <EarningsTodayCard earnings={artistEarningsToday} />
        <NextAppointmentsSummary bookings={bookings} />
      </div>
    </div>
  )
}

function ReceptionistHero({ inventoryAlerts }: { inventoryAlerts: InventoryAlertsData | null | undefined }) {
  const queueQuery = useTodayQueue(true)
