'use client'

import { useTodayQueue } from '@/hooks/use-today-queue'
import { TodayQueue } from './TodayQueue'
import { formatCurrency } from '@/lib/utils'
import { cn } from '@/lib/utils'
import { AlertTriangle, CalendarDays, Clock, ShieldAlert } from 'lucide-react'
import type { StockAlert } from '@/lib/supabase/types'

interface InventoryAlertsData {
  open_alerts_count: number
  items_below_threshold: number
  total_items: number
  open_alerts: StockAlert[]
}
import type { TodayBooking } from '@/hooks/use-today-queue'

type StudioRole = 'owner' | 'admin' | 'artist' | 'receptionist' | 'guest_artist'

interface RoleAwareHeroProps {
  role: StudioRole
  studioId: string
  /** Artist's own artist_id — only populated when role === 'artist' or 'guest_artist' */
  ownArtistId?: string | null | undefined
  /** Artist earnings today (cents) — pre-fetched server-side for artist/guest_artist roles */
  artistEarningsToday?: number | undefined
  /** Inventory alerts data for receptionist role */
  inventoryAlerts?: InventoryAlertsData | null | undefined
}

// ─── Shared section header ────────────────────────────────────────────────────

function SectionLabel({ children }: { children: React.ReactNode }) {
  return (
    <h2 className="mb-2 text-[11px] font-semibold uppercase tracking-[0.08em] text-[var(--color-muted-foreground)]">
      {children}
    </h2>
  )
}

// ─── Artist earnings card ─────────────────────────────────────────────────────

function EarningsTodayCard({ earnings }: { earnings: number }) {
  return (
    <div className="rounded-xl border border-[var(--color-border)] bg-[var(--color-card)] p-4 shadow-[var(--shadow-soft)]">
      <p className="text-[11px] font-medium uppercase tracking-[0.08em] text-[var(--color-muted-foreground)]">
        My Earnings Today
      </p>
      <p className="mt-1 text-2xl font-bold tracking-tight text-[var(--color-success-foreground)]">
        {formatCurrency(earnings, 'USD')}
      </p>
      <p className="mt-0.5 text-[11px] text-[var(--color-muted-foreground)]">
        from completed sessions
      </p>
    </div>
  )
}

// ─── Next appointments summary (artist) ──────────────────────────────────────

function NextAppointmentsSummary({ bookings }: { bookings: TodayBooking[] }) {
  const now = new Date()
  const upcoming = bookings
    .filter(
      (b) =>
        new Date(b.scheduled_at) >= now &&
        b.status !== 'cancelled' &&
        b.status !== 'completed',
    )
    .slice(0, 3)

  if (upcoming.length === 0) {
    return (
      <div className="rounded-xl border border-[var(--color-border)] bg-[var(--color-card)] p-4 shadow-[var(--shadow-soft)]">
        <p className="text-[11px] font-medium uppercase tracking-[0.08em] text-[var(--color-muted-foreground)]">
          My Next Appointments
        </p>
