'use client'

import { useEffect, useState } from 'react'
import { CalendarDays, CreditCard, DollarSign, Users } from 'lucide-react'
import { Typography } from '@/components/ui/typography'
import { KpiCard } from '@/components/shared/KpiCard'
import { KpiCardSkeleton } from '@/components/shared/KpiCardSkeleton'
import { ActivityFeed } from '@/components/shared/ActivityFeed'
import { AlertsCard } from '@/components/shared/AlertsCard'
import { InventoryAlertsCard } from '@/components/inventory/InventoryAlertsCard'
import { GettingStartedCard } from '@/components/dashboard/GettingStartedCard'
import { TodayAgendaWidget } from '@/components/dashboard/TodayAgendaWidget'
import { QuickActionsRow } from '@/components/dashboard/QuickActionsRow'
import { EmptyDashboardState } from '@/components/dashboard/EmptyDashboardState'
import { useDashboardKpis } from '@/hooks/dashboard/use-dashboard-kpis'
import { useTodayAgenda } from '@/hooks/dashboard/use-today-agenda'
import { useRecentActivity } from '@/hooks/dashboard/use-recent-activity'
import { useInventoryAlerts } from '@/hooks/dashboard/use-inventory-alerts'
import { useDashboardAlerts } from '@/hooks/dashboard/use-dashboard-alerts'
import { useRouter } from 'next/navigation'
import type { GettingStartedCounts } from '@/components/dashboard/GettingStartedCard'
import { RoleAwareHero } from './RoleAwareHero'
import { TodayQuickActionsRow } from './QuickActionsRow'
import type { Database } from '@/lib/supabase/types'

type StudioRole = Database['public']['Tables']['studio_members']['Row']['role']

interface TodayClientProps {
  firstName: string
  studioName: string
  hasStudio: boolean
  studioId: string | null
  role: StudioRole
  ownArtistId?: string | null
  artistEarningsToday?: number
  gettingStartedCounts: GettingStartedCounts
}

function formatDate(): string {
  return new Date().toLocaleDateString('en-US', {
    weekday: 'long',
    month: 'long',
    day: 'numeric',
  })
}

export function TodayClient({
  firstName,
  studioName,
  hasStudio,
  studioId,
  role,
  ownArtistId,
  artistEarningsToday = 0,
  gettingStartedCounts,
}: TodayClientProps) {
  const router = useRouter()
  const kpisQuery = useDashboardKpis(hasStudio)
  const agendaQuery = useTodayAgenda(hasStudio)
  const activityQuery = useRecentActivity(hasStudio)
  const inventoryAlertsQuery = useInventoryAlerts(hasStudio)
  const alertsQuery = useDashboardAlerts(hasStudio)

  const kpis = kpisQuery.data
  const kpisLoading = kpisQuery.isLoading || kpisQuery.isFetching

  const [dismissedIds, setDismissedIds] = useState<string[]>([])

  const [checklistDismissed, setChecklistDismissed] = useState(false)
  useEffect(() => {
    setChecklistDismissed(
      localStorage.getItem('inkos:getting-started:dismissed') === '1',
    )
  }, [])

  // N shortcut — new appointment
  useEffect(() => {
    const handler = (e: KeyboardEvent) => {
      const target = e.target as HTMLElement
      const tag = target.tagName
      if (
        tag === 'INPUT' ||
        tag === 'TEXTAREA' ||
        tag === 'SELECT' ||
        target.isContentEditable
      )
        return
      if (e.key === 'n' || e.key === 'N') {
        e.preventDefault()
        router.push('/appointments/new')
      }
    }
    window.addEventListener('keydown', handler)
    return () => window.removeEventListener('keydown', handler)
  }, [router])

  const visibleAlerts = (alertsQuery.data ?? []).filter(
    (a) => !dismissedIds.includes(a.id),
  )

  const showEmptyState =
    checklistDismissed && gettingStartedCounts.bookings === 0

  const revenueMtd = kpis?.revenueMtd ?? 0
  const revenueMtdDelta = kpis?.revenueMtdDelta ?? '0%'
  const apptTodayCount = kpis?.apptTodayCount ?? 0
  const apptTodayCompleted = kpis?.apptTodayCompleted ?? 0
  const apptTodayPending = kpis?.apptTodayPending ?? 0
  const newClientsMtd = kpis?.newClientsMtd ?? 0
  const newClientsMtdDelta = kpis?.newClientsMtdDelta ?? '0%'
  const pendingDepositsTotal = kpis?.pendingDepositsTotal ?? 0
  const pendingDepositsCount = kpis?.pendingDepositsCount ?? 0
  const pendingDepositsDelta = kpis?.pendingDepositsDelta ?? '0%'

  const agendaAppointments = agendaQuery.data ?? []
  const totalToday = agendaAppointments.length

  // KPI row: owner/admin only — artists see earnings inside RoleAwareHero
  const showKpis = role === 'owner' || role === 'admin'

  return (
    <div className="min-h-full bg-[var(--color-page-bg)]">
      <div className="mx-auto max-w-[1440px] space-y-6 px-4 pb-10 pt-6 sm:px-6 lg:px-8">

        {/* ── Header ── */}
        <div className="flex flex-col gap-3 sm:flex-row sm:items-start sm:justify-between">
          <div>
            <p className="mb-0.5 text-xs font-medium uppercase tracking-[0.08em] text-muted-foreground">
              {studioName}
            </p>
            <Typography variant="h1" className="text-foreground">
              Your day,{' '}
              <span className="text-primary">{firstName}</span>
            </Typography>
            <p className="mt-0.5 text-sm text-muted-foreground">{formatDate()}</p>
          </div>
        </div>

        {/* ── Today quick actions (card grid with descriptions) ── */}
        <TodayQuickActionsRow />

        {/* ── Legacy quick actions toolbar (shortcut buttons) ── */}
        <QuickActionsRow />

        {/* ── Getting started checklist ── */}
        <GettingStartedCard counts={gettingStartedCounts} />

        {showEmptyState ? (
          <EmptyDashboardState />
        ) : (
          <>
            {/* ── Role-aware hero: TodayQueue + role-specific widgets ── */}
            {hasStudio && studioId && (
              <RoleAwareHero
                role={role}
                studioId={studioId}
                ownArtistId={ownArtistId}
                artistEarningsToday={artistEarningsToday}
                inventoryAlerts={inventoryAlertsQuery.data}
              />
            )}

            {/* ── KPI row — owner/admin only ── */}
            {showKpis && (
              <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-4">
                {kpisLoading ? (
                  Array.from({ length: 4 }).map((_, i) => <KpiCardSkeleton key={i} />)
                ) : (
                  <>
                    <KpiCard
                      label="Revenue MTD"
                      value={revenueMtd}
                      formatter={(n) =>
                        n >= 100_000
                          ? `$${(n / 100_000).toFixed(1)}k`
                          : `$${(n / 100).toLocaleString()}`
                      }
                      delta={revenueMtdDelta}
                      trend={revenueMtdDelta.startsWith('+') ? 'up' : 'down'}
                      subtextLabel="vs last month"
                      {...(kpis?.revenueDailyLast30 !== undefined ? { sparkline: kpis.revenueDailyLast30 } : {})}
                      icon={DollarSign}
                      accentVar="var(--color-status-completed)"
                      hoverVariant="lift"
                      index={0}
                    />
                    <div
                      role="link"
                      tabIndex={0}
                      onClick={() =>
                        document
                          .getElementById('today-agenda')
                          ?.scrollIntoView({ behavior: 'smooth' })
                      }
                      onKeyDown={(e) => {
                        if (e.key === 'Enter') {
                          document
                            .getElementById('today-agenda')
                            ?.scrollIntoView({ behavior: 'smooth' })
                        }
                      }}
                      className="cursor-pointer"
                      aria-label="Scroll to today's agenda"
                    >
                      <KpiCard
                        label="Appointments Today"
                        value={apptTodayCount}
                        subtextLabel={`${apptTodayCompleted} completed · ${apptTodayPending} pending`}
                        icon={CalendarDays}
                        trend="neutral"
                        accentVar="var(--color-primary)"
                        hoverVariant="lift"
                        index={1}
                      />
                    </div>
                    <KpiCard
                      label="New Clients MTD"
                      value={newClientsMtd}
                      delta={newClientsMtdDelta}
                      trend={newClientsMtdDelta.startsWith('+') ? 'up' : 'down'}
                      subtextLabel="vs last month"
                      {...(kpis?.newClientsDailyLast30 !== undefined ? { sparkline: kpis.newClientsDailyLast30 } : {})}
                      icon={Users}
                      accentVar="var(--color-accent-foreground)"
                      hoverVariant="lift"
                      index={2}
                    />
                    <KpiCard
                      label="Pending Deposits"
                      value={pendingDepositsTotal}
                      formatter={(n) =>
                        n >= 100_000
                          ? `$${(n / 100_000).toFixed(1)}k`
                          : `$${(n / 100).toLocaleString()}`
                      }
                      delta={pendingDepositsDelta}
                      trend={pendingDepositsCount > 0 ? 'up' : 'down'}
                      invertTrend
                      subtextLabel={`${pendingDepositsCount} booking${pendingDepositsCount !== 1 ? 's' : ''}`}
                      icon={CreditCard}
                      accentVar="var(--color-warning)"
                      hoverVariant="lift"
                      index={3}
                    />
                  </>
                )}
              </div>
            )}

            {/* ── Agenda + Activity ── */}
            <div className="grid grid-cols-1 gap-4 lg:grid-cols-12">
              <div className="lg:col-span-8">
                <TodayAgendaWidget
                  appointments={agendaAppointments}
                  totalToday={totalToday}
                  loading={agendaQuery.isLoading}
                />
              </div>
              <div className="lg:col-span-4">
                <ActivityFeed
                  events={activityQuery.data ?? []}
                  loading={activityQuery.isLoading}
                  {...(studioId !== null ? { studioId } : {})}
                />
              </div>
            </div>

            {/* ── Alerts ── */}
            <div className="grid grid-cols-1 gap-4">
              <AlertsCard
                alerts={visibleAlerts}
                loading={alertsQuery.isLoading}
                onDismiss={(id) =>
                  setDismissedIds((prev) => [...prev, id])
                }
              />
              {inventoryAlertsQuery.data != null && (
                <InventoryAlertsCard
                  openAlertsCount={inventoryAlertsQuery.data.open_alerts_count}
                  itemsBelowThreshold={inventoryAlertsQuery.data.items_below_threshold}
                  loading={inventoryAlertsQuery.isLoading}
                />
              )}
            </div>
          </>
        )}

      </div>
    </div>
  )
}

'use client'

import { useState, useRef, useLayoutEffect } from 'react'
import Link from 'next/link'
import { CheckCircle2, Circle, X } from 'lucide-react'
import { Typography } from '@/components/ui/typography'
import { cn } from '@/lib/utils'

const DISMISS_KEY = 'inkos:getting-started:dismissed'

export interface GettingStartedCounts {
  services: number
  artists: number
  schedules: number
  bookings: number
  bookingPageConfigured: boolean
}

interface Step {
  id: string
  label: string
  description: string
  href: string
  done: boolean
}

function buildSteps(counts: GettingStartedCounts): Step[] {
  return [
    {
      id: 'service',
      label: 'Add your first service',
      description: 'Define what you offer — tattoo styles, consultations, touch-ups.',
      href: '/settings/services',
      done: counts.services > 0,
    },
    {
      id: 'artist',
      label: 'Create your artist profile',
      description: 'Set up your profile so clients can book with you.',
      href: '/artists',
      done: counts.artists > 0,
    },
    {
      id: 'schedule',
      label: 'Set up your availability',
      description: 'Define your working hours so the booking calendar knows when you\'re free.',
      href: '/artists',
      done: counts.schedules > 0,
    },
    {
      id: 'booking',
      label: 'Book your first appointment',
      description: 'Create a booking manually or share your booking link.',
      href: '/appointments/new',
      done: counts.bookings > 0,
    },
    {
      id: 'booking-page',
      label: 'Customize your booking page',
      description: 'Add your studio branding so clients trust the experience.',
      href: '/settings/booking-page',
      done: counts.bookingPageConfigured,
    },
  ]
}

interface GettingStartedCardProps {
  counts: GettingStartedCounts
}

export function GettingStartedCard({ counts }: GettingStartedCardProps) {
  const [dismissed, setDismissed] = useState<boolean>(() => {
    if (typeof window === 'undefined') return false
    return localStorage.getItem(DISMISS_KEY) === '1'
  })
  // Use a ref to track mount for SSR-safe rendering
  const mounted = useRef(typeof window !== 'undefined')
  // Re-sync dismissed from storage once mounted (covers SSR → hydration)
  useLayoutEffect(() => {
    mounted.current = true
    const stored = localStorage.getItem(DISMISS_KEY) === '1'
    if (stored !== dismissed) setDismissed(stored)
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  const steps = buildSteps(counts)
  const completedCount = steps.filter((s) => s.done).length
  const allDone = completedCount === steps.length

  const handleDismiss = () => {
    localStorage.setItem(DISMISS_KEY, '1')
    setDismissed(true)
  }

  // Hide if dismissed or all done
  if (dismissed || allDone) return null

  const progressPct = Math.round((completedCount / steps.length) * 100)

  return (
    <div
      className={cn(
        'relative rounded-xl border border-border/60 bg-card overflow-hidden',
        'before:absolute before:inset-0 before:rounded-xl before:pointer-events-none',
        'before:border before:border-[hsl(var(--color-electric-purple)/0.25)]',
      )}
      style={{
        background:
          'linear-gradient(135deg, hsl(var(--card)) 0%, hsl(var(--color-electric-purple)/0.04) 100%)',
      }}
    >
      {/* Dismiss */}
      <button
        onClick={handleDismiss}
        aria-label="Dismiss getting started checklist"
        className="absolute top-3 right-3 p-1 rounded-md text-muted-foreground hover:text-foreground hover:bg-muted/60 transition-colors"
      >
        <X className="h-4 w-4" />
      </button>

      <div className="px-6 pt-5 pb-6 space-y-4">
        {/* Header */}
        <div>
          <Typography variant="h2" className="tracking-tight">Get your studio ready</Typography>
          <p className="mt-0.5 text-xs text-muted-foreground">
            Complete these steps to go live — {completedCount}/{steps.length} done
          </p>
        </div>

        {/* Progress bar */}
        <div className="relative h-1.5 w-full rounded-full bg-muted overflow-hidden">
          <div
            className="absolute inset-y-0 left-0 rounded-full transition-all duration-700"
            style={{
              width: `${progressPct}%`,
              background: 'linear-gradient(90deg, hsl(var(--color-electric-purple)) 0%, hsl(var(--primary)) 100%)',
            }}
          />
        </div>

        {/* Steps */}
        <ol className="space-y-2.5">
          {steps.map((step, idx) => (
            <li
              key={step.id}
              className={cn(
                'flex items-start gap-3 group',
                step.done && 'opacity-60',
              )}
              style={{
                animationDelay: `${idx * 60}ms`,
                animationFillMode: 'both',
              }}
            >
              {step.done ? (
                <CheckCircle2 className="mt-0.5 h-4 w-4 shrink-0 text-[hsl(var(--color-electric-purple))]" />
              ) : (
                <Circle className="mt-0.5 h-4 w-4 shrink-0 text-muted-foreground/40" />
              )}
              <div className="flex-1 min-w-0">
                <Link
                  href={step.href}
                  className={cn(
                    'text-sm font-medium leading-none hover:underline underline-offset-2 transition-colors',
                    step.done
                      ? 'line-through text-muted-foreground'
                      : 'text-foreground group-hover:text-primary',
                  )}
                >
                  {step.label}
                </Link>
                {!step.done && (
                  <p className="mt-0.5 text-xs text-muted-foreground leading-snug">
                    {step.description}
                  </p>
                )}
              </div>
              {!step.done && (
                <Link
                  href={step.href}
                  className="h-6 px-2 text-xs shrink-0 opacity-0 group-hover:opacity-100 transition-opacity inline-flex items-center rounded-md hover:bg-muted text-muted-foreground hover:text-foreground"
                >
                  Go →
                </Link>
              )}
            </li>
          ))}
        </ol>
      </div>
    </div>
  )
}

