export function GettingStartedCard({ counts }: GettingStartedCardProps) {
  // SSR-safe: always start `false` on both server and first client render, then
  // sync from localStorage after hydration. Returning null during SSR while the
  // client returns null (or the card) causes a tree-shift hydration mismatch,
  // so we render the card on the first paint and hide it on the next tick.
  const [hydrated, setHydrated] = useState(false)
  const [dismissed, setDismissed] = useState(false)

  useEffect(() => {
    setHydrated(true)
    setDismissed(localStorage.getItem(DISMISS_KEY) === '1')
  }, [])

  const steps = buildSteps(counts)
  const completedCount = steps.filter((s) => s.done).length
  const allDone = completedCount === steps.length

  const handleDismiss = () => {
    localStorage.setItem(DISMISS_KEY, '1')
    setDismissed(true)
  }

  // Hide only after hydration to match SSR output on first paint.
  if (hydrated && (dismissed || allDone)) return null

